<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';
$checks=0;
$ok=static function(bool $value,string $label)use(&$checks):void{$checks++;if(!$value)throw new RuntimeException('Video rule failed: '.$label);};
$idA=str_repeat('a',32);$idB=str_repeat('b',32);$mediaA=str_repeat('c',32);$mediaB=str_repeat('d',32);
$clip=static fn($id,$media,$start,$end):array=>['id'=>$id,'mediaId'=>$media,'durationMs'=>15000,'trimStartMs'=>$start,'trimEndMs'=>$end,'volume'=>1,'audioKeyframes'=>[], 'overlayText'=>'', 'transition'=>'cut'];
$timeline=['settings'=>['detachedAudio'=>[]], 'clips'=>[$clip($idA,$mediaA,0,12000),$clip($idB,$mediaB,0,9000)]];
$annotations=[['mediaId'=>$mediaA,'kind'=>'highlight','note'=>'Owner selected this take','startMs'=>1000,'endMs'=>4500],['mediaId'=>$mediaB,'kind'=>'caption','note'=>'My own caption','startMs'=>2000,'endMs'=>7000]];
$plan=az_video_agent_suggest($timeline,$annotations,6,'highlight',false);
$ok(count($plan['timeline']['clips'])===2,'two selections');
$ok($plan['durationMs']===6000,'bounded runtime');
$ok($plan['timeline']['clips'][0]['trimStartMs']===1000,'creator highlight anchors trim');
$ok($plan['timeline']['clips'][0]['trimEndMs']===4500,'creator highlight end bound');
$ok($plan['timeline']['clips'][1]['trimStartMs']===2000 && $plan['timeline']['clips'][1]['trimEndMs']===4500,'budget remaining');
$ok($plan['timeline']['clips'][1]['overlayText']==='', 'captions opt-in not automatic');
$with=az_video_agent_suggest($timeline,$annotations,15,'recap',true);
$ok($with['timeline']['clips'][1]['overlayText']==='My own caption','caption copied only with opt-in');
$ok($timeline['clips'][0]['trimStartMs']===0,'source timeline unmodified');
$plain=az_video_agent_suggest($timeline,[],5,'teaser');
$ok($plain['timeline']['clips'][0]['trimStartMs']===3500,'unannotated source midpoint');
$ok($plain['durationMs']===5000,'teaser runtime');
$audio=$timeline;$audio['settings']['detachedAudio']=[['id'=>str_repeat('e',32)]];
$warn=az_video_agent_suggest($audio,[],15,'recap');
$ok(empty($warn['timeline']['settings']['detachedAudio']) && count($warn['warnings'])>=2,'A2 sound omission disclosed');
foreach([['startMs'=>0,'endMs'=>50,'kind'=>'highlight','note'=>'abc'],['startMs'=>100,'endMs'=>20000,'kind'=>'highlight','note'=>'abc'],['startMs'=>0,'endMs'=>500,'kind'=>'unknown','note'=>'abc'],['startMs'=>0,'endMs'=>500,'kind'=>'caption','note'=>'']] as $invalid){$thrown=false;try{az_video_agent_moment_input($invalid,12000);}catch(AzHttpError $e){$thrown=$e->status===400;}$ok($thrown,'invalid moment rejected');}
$valid=az_video_agent_moment_input(['startMs'=>0,'endMs'=>1000,'kind'=>'caption','note'=>'  Hello  '],12000);
$ok($valid['note']==='Hello','note stripped');
$ok(az_video_agent_rules(['status'=>'proposed','updated_at'=>'2026-11-18T00:00:00Z'],strtotime('2026-11-21T00:00:00Z'))===['review_48h'],'stale plan reminder');
$ok(az_video_agent_rules(['status'=>'applied','updated_at'=>'2026-11-18T00:00:00Z'],strtotime('2026-11-21T00:00:00Z'))===[],'completed plan never nagged');
$ok(az_video_agent_rules(['status'=>'proposed','updated_at'=>'2026-11-20T00:00:00Z'],strtotime('2026-11-21T00:00:00Z'))===[],'fresh plan not nagged');
foreach([['goal'=>'','target'=>15],['goal'=>'highlight','target'=>1],['goal'=>'highlight','target'=>301]] as $invalid){$thrown=false;try{az_video_agent_suggest($timeline,[],$invalid['target'],$invalid['goal']);}catch(AzHttpError){$thrown=true;}$ok($thrown,'invalid plan rejected');}
$keyframes=[['timeMs'=>0,'volume'=>0.2],['timeMs'=>6000,'volume'=>0.8],['timeMs'=>12000,'volume'=>0.5]];
$cutAudio=az_video_agent_rebase_audio($keyframes,0,3000,9000,1.0);
$ok(count($cutAudio)===3,'audio keyframes keep inside turning point and new boundaries');
$ok(abs($cutAudio[0]['volume']-0.5)<0.001 && $cutAudio[0]['timeMs']===0,'audio envelope interpolates new left trim boundary');
$ok(abs($cutAudio[2]['volume']-0.65)<0.001 && $cutAudio[2]['timeMs']===6000,'audio envelope interpolates new right trim boundary');
$ok($cutAudio[1]['timeMs']===3000 && abs($cutAudio[1]['volume']-0.8)<0.001,'audio keyframe retains its local relative time');
$titleClip=$clip($idA,$mediaA,0,12000);$titleClip['titleCard']=true;
$titlePlan=az_video_agent_suggest(['settings'=>['cardDuration'=>2.5],'clips'=>[$titleClip]],[],5,'teaser');
$ok($titlePlan['durationMs']===5000,'title card included in requested duration budget');
$ok($titlePlan['timeline']['clips'][0]['trimEndMs']-$titlePlan['timeline']['clips'][0]['trimStartMs']===2500,'title card leaves only available video budget');
$issue=az_video_agent_suggest($timeline,[$annotations[0],['mediaId'=>$mediaA,'kind'=>'issue','startMs'=>2000,'endMs'=>2500,'note'=>'Noise']],6,'highlight');
$ok(count(array_filter($issue['warnings'],static fn($w)=>str_contains($w,'creator-flagged issue')))>0,'creator-flagged issue is surfaced without claiming footage analysis');
$withTracks=$timeline;$withTracks['settings']['timedTitles']=[['id'=>str_repeat('f',32),'startMs'=>0,'durationMs'=>3000,'text'=>'Title']];
$withTracks['settings']['background']=['mediaId'=>$mediaA,'startMs'=>0,'trimStartMs'=>0,'volume'=>0.25];
$warnings=az_video_agent_suggest($withTracks,[],5,'teaser')['warnings'];
$ok(count(array_filter($warnings,static fn($w)=>str_contains($w,'B1 background')))>0,'background audio timing warning');
$ok(count(array_filter($warnings,static fn($w)=>str_contains($w,'T1 timed-title')))>0,'timed-title warning');
echo "Video specialist pure rule checks: $checks passed\n";
